@import url('https://fonts.googleapis.com/css2?family=Fredoka:wght@500;600;700&family=Nunito:wght@500;600;700;800;900&display=swap');

* {
    box-sizing: border-box;
}

.modo-sano {
    max-width: 1100px;
    margin: 30px auto;
    padding: 0 18px;
    font-family: 'Nunito', sans-serif;
    color: #263238;
}

/* =========================
   PORTADA
========================= */

.modo-sano .hero {
    position: relative;
    overflow: hidden;
    min-height: 410px;
    border-radius: 38px;
    background: linear-gradient(135deg, #4a148c, #7b1fa2, #e91e63);
    color: white;
    display: flex;
    justify-content: center;
    align-items: center;
    text-align: center;
    padding: 50px 25px;
    box-shadow: 0 20px 45px rgba(74,20,140,.28);
}

.modo-sano .hero::before {
    content: "";
    position: absolute;
    width: 430px;
    height: 430px;
    background: #ffca28;
    border-radius: 50%;
    top: -260px;
    left: -130px;
    opacity: .16;
}

.modo-sano .hero::after {
    content: "";
    position: absolute;
    width: 400px;
    height: 400px;
    background: #00bcd4;
    border-radius: 50%;
    right: -150px;
    bottom: -250px;
    opacity: .18;
}

.hero-contenido {
    position: relative;
    z-index: 2;
}

.hero-iconos {
    font-size: 75px;
    margin-bottom: 10px;
    animation: flotar 2.5s ease-in-out infinite;
}

.modo-sano .hero h1 {
    font-family: 'Fredoka', sans-serif;
    font-size: 62px;
    line-height: .95;
    margin: 0;
    font-weight: 700;
    letter-spacing: 1px;
    text-shadow: 5px 6px 0 rgba(50,0,70,.35);
}

.modo-sano .hero p {
    font-size: 20px;
    font-weight: 700;
    margin: 22px auto 0;
    max-width: 700px;
    color: #ffe8f4;
}

/* =========================
   TITULOS
========================= */

.seccion-titulo {
    text-align: center;
    margin: 55px 0 25px;
}

.seccion-numero {
    display: inline-flex;
    width: 48px;
    height: 48px;
    align-items: center;
    justify-content: center;
    background: #e91e63;
    color: white;
    border-radius: 50%;
    font-weight: 900;
    box-shadow: 0 7px 15px rgba(233,30,99,.25);
}

.seccion-titulo h2 {
    font-family: 'Fredoka', sans-serif;
    font-size: 42px;
    color: #4a148c;
    margin: 10px 0 0;
}

.seccion-titulo h2 span {
    color: #e91e63;
}

/* =========================
   INTRODUCCION
========================= */

.introduccion {
    background: white;
    border-radius: 30px;
    padding: 35px;
    display: grid;
    grid-template-columns: 100px 1fr;
    gap: 25px;
    align-items: center;
    box-shadow: 0 10px 28px rgba(0,0,0,.08);
    border-bottom: 7px solid #7b1fa2;
}

.intro-icono {
    width: 90px;
    height: 90px;
    background: #f3e5f5;
    border-radius: 26px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 48px;
}

.introduccion p {
    font-size: 18px;
    line-height: 1.8;
    margin: 0 0 10px;
}

.introduccion p:last-child {
    margin-bottom: 0;
}

/* =========================
   MENSAJE CENTRAL
========================= */

.mensaje-central {
    margin-top: 25px;
    background: linear-gradient(135deg,#fff8e1,#fff3cd);
    border-radius: 30px;
    padding: 35px;
    text-align: center;
    border: 2px solid #ffca28;
    box-shadow: 0 10px 25px rgba(255,193,7,.12);
}

.mensaje-central .iconos {
    font-size: 58px;
}

.mensaje-central h2 {
    font-family: 'Fredoka', sans-serif;
    font-size: 34px;
    color: #f57f17;
    margin: 10px 0;
}

.mensaje-central p {
    font-size: 17px;
    line-height: 1.7;
}

/* =========================
   RUTA DE APRENDIZAJE
========================= */

.ruta {
    margin-top: 55px;
    background: #f3e5f5;
    border-radius: 35px;
    padding: 40px;
}

.ruta h2 {
    text-align: center;
    font-family: 'Fredoka', sans-serif;
    color: #6a1b9a;
    font-size: 40px;
    margin: 0 0 30px;
}

.ruta-grid {
    display: grid;
    grid-template-columns: repeat(4,1fr);
    gap: 18px;
}

.ruta-card {
    background: white;
    border-radius: 25px;
    padding: 28px 18px;
    text-align: center;
    min-height: 220px;
    box-shadow: 0 7px 18px rgba(0,0,0,.07);
    transition: .35s;
    position: relative;
    overflow: hidden;
}

.ruta-card:hover {
    transform: translateY(-10px) scale(1.03);
    box-shadow: 0 18px 30px rgba(0,0,0,.14);
}

.ruta-card:nth-child(1) {
    border-top: 7px solid #ff7043;
}

.ruta-card:nth-child(2) {
    border-top: 7px solid #00acc1;
}

.ruta-card:nth-child(3) {
    border-top: 7px solid #ab47bc;
}

.ruta-card:nth-child(4) {
    border-top: 7px solid #ffa000;
}

.ruta-card .emoji {
    font-size: 55px;
    transition: .3s;
}

.ruta-card:hover .emoji {
    transform: scale(1.18) rotate(5deg);
}

.ruta-card h3 {
    font-family: 'Fredoka', sans-serif;
    font-size: 25px;
    margin: 12px 0 7px;
    color: #4a148c;
}

.ruta-card p {
    font-size: 15px;
    line-height: 1.6;
    margin: 0;
}

/* =========================
   FRASE FINAL
========================= */

.frase-final {
    margin-top: 55px;
    border-radius: 35px;
    padding: 50px 25px;
    text-align: center;
    color: white;
    background:
        radial-gradient(circle at 15% 20%,#ff4081 0,transparent 25%),
        radial-gradient(circle at 85% 80%,#00bcd4 0,transparent 25%),
        #311b92;
    box-shadow: 0 20px 45px rgba(49,27,146,.25);
}

.frase-final .emoji {
    font-size: 65px;
}

.frase-final h2 {
    font-family: 'Fredoka', sans-serif;
    font-size: 45px;
    margin: 8px 0;
}

.frase-final p {
    font-size: 18px;
    max-width: 700px;
    margin: auto;
    line-height: 1.7;
    color: #f3e5f5;
}

/* =========================
   ANIMACION
========================= */

@keyframes flotar {
    0%,100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-12px);
    }
}

/* =========================
   RESPONSIVE
========================= */

@media(max-width:800px) {

    .ruta-grid {
        grid-template-columns: 1fr 1fr;
    }

    .modo-sano .hero h1 {
        font-size: 48px;
    }
}

@media(max-width:500px) {

    .ruta-grid {
        grid-template-columns: 1fr;
    }

    .introduccion {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .intro-icono {
        margin: auto;
    }

    .modo-sano .hero h1 {
        font-size: 38px;
    }

    .seccion-titulo h2,
    .ruta h2 {
        font-size: 32px;
    }

    .frase-final h2 {
        font-size: 35px;
    }

    .ruta,
    .introduccion {
        padding: 25px 20px;
    }
}
</style>
<div class="modo-sano"><!-- PORTADA -->
<div class="hero">
<div class="hero-contenido">
