    box-shadow: 0 15px 40px rgba(0, 105, 92, .15);
    border: 2px solid #d7f3ed;
}

/* =========================
   ENCABEZADO
========================= */

.habitos-encabezado {
    position: relative;
    overflow: hidden;
    padding: 45px 25px;
    text-align: center;
    color: white;
    background: linear-gradient(135deg, #00695c, #00a884, #26c6a5);
}

.habitos-encabezado::before {
    content: "🍎";
    position: absolute;
    font-size: 150px;
    left: -25px;
    top: -55px;
    opacity: .10;
    animation: girar 8s linear infinite;
}

.habitos-encabezado::after {
    content: "💚";
    position: absolute;
    font-size: 150px;
    right: -25px;
    bottom: -60px;
    opacity: .10;
    animation: flotar 3s ease-in-out infinite;
}

.habitos-icono {
    font-size: 65px;
    animation: rebote 2s ease-in-out infinite;
    position: relative;
    z-index: 2;
}

.habitos-encabezado h2 {
    font-family: 'Fredoka', sans-serif;
    font-size: 42px;
