    position: relative;
    z-index: 2;
}

/* =========================
   CONTENIDO
========================= */

.habitos-contenido {
    padding: 38px;
}

/* TARJETA INTRO */
.habitos-intro {
    background: linear-gradient(135deg, #e0f7fa, #e8f5e9);
    border-left: 8px solid #00a884;
    padding: 23px 25px;
    border-radius: 20px;
    margin-bottom: 25px;
    transition: .3s;
}

.habitos-intro:hover {
    transform: translateX(7px);
    box-shadow: 0 8px 20px rgba(0,137,123,.12);
}

.habitos-intro p {
    margin: 0;
    font-size: 18px;
    line-height: 1.8;
}

/* TEXTO */
.habitos-texto {
    font-size: 18px;
    line-height: 1.8;
    text-align: center;
    max-width: 850px;
    margin: 25px auto;
}

/* =========================
   ICONOS DE HABITOS
========================= */

.habitos-iconos {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 15px;
    margin: 30px 0;
}

.habito {
    padding: 20px 12px;
    text-align: center;
    background: white;
    border-radius: 22px;
    box-shadow: 0 7px 20px rgba(0,0,0,.07);
    transition: .35s;
}

.habito:hover {
    transform: translateY(-10px) scale(1.03);
}

.habito:nth-child(1) {
    border-top: 6px solid #ff7043;
}

.habito:nth-child(2) {
    border-top: 6px solid #5e35b1;
}

.habito:nth-child(3) {
    border-top: 6px solid #039be5;
}

.habito:nth-child(4) {
    border-top: 6px solid #43a047;
}

.habito .emoji {
    font-size: 43px;
    display: inline-block;
    animation: flotar 3s ease-in-out infinite;
}

.habito h3 {
    font-family: 'Fredoka', sans-serif;
    color: #00695c;
    margin: 8px 0 0;
    font-size: 20px;
}

/* =========================
   VIDEO
========================= */

.video-seccion {
    margin-top: 35px;
    padding: 32px;
    text-align: center;
    border-radius: 28px;
    background: linear-gradient(135deg, #e3f2fd, #e0f7fa);
    border: 3px solid #81d4fa;
}

.video-seccion h3 {
    font-family: 'Fredoka', sans-serif;
    color: #0277bd;
    font-size: 32px;
    margin: 0 0 8px;
}

.video-seccion p {
    font-size: 17px;
    margin: 0 auto 25px;
}

/* MINI DESTACADO */
.video-destacado {
    display: inline-block;
    background: #ffffff;
    padding: 10px 22px;
    border-radius: 50px;
    color: #00897b;
    font-weight: 900;
    margin-bottom: 22px;
    box-shadow: 0 5px 15px rgba(0,0,0,.08);
    animation: pulso 2s infinite;
}

/* IMAGEN VIDEO */
.video-imagen {
    display: block;
    width: 100%;
    max-width: 700px;
    margin: auto;
    border-radius: 22px;
    box-shadow: 0 12px 28px rgba(0,0,0,.2);
    transition: .4s;
}

.video-imagen:hover {
    transform: scale(1.025);
    box-shadow: 0 18px 35px rgba(0,0,0,.28);
}

/* BOTON */
.video-boton {
    display: inline-block;
    margin-top: 22px;
    padding: 15px 32px;
    border-radius: 50px;
    background: linear-gradient(135deg, #e53935, #ff5252);
    color: white;
    text-decoration: none;
    font-size: 18px;
    font-weight: 900;
    box-shadow: 0 8px 18px rgba(229,57,53,.3);
    transition: .3s;
}

.video-boton:hover {
    transform: translateY(-5px) scale(1.05);
    box-shadow: 0 13px 25px rgba(229,57,53,.4);
}

/* =========================
   MENSAJE FINAL
========================= */

.habitos-final {
    margin-top: 35px;
    padding: 28px;
    text-align: center;
    border-radius: 25px;
    background: linear-gradient(135deg, #00695c, #26a69a);
    color: white;
}

.habitos-final .emoji {
    font-size: 45px;
}

.habitos-final strong {
    font-family: 'Fredoka', sans-serif;
    font-size: 25px;
}

/* =========================
   ANIMACIONES
========================= */

@keyframes flotar {
    0%,100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-8px);
    }
}

@keyframes rebote {
    0%,100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-12px) rotate(3deg);
    }
}

@keyframes pulso {
    0%,100% {
        transform: scale(1);
    }
    50% {
        transform: scale(1.04);
    }
}

@keyframes girar {
    from {
        transform: rotate(0deg);
    }
    to {
        transform: rotate(360deg);
    }
}

/* =========================
   RESPONSIVE
========================= */

@media(max-width:700px) {

    .habitos-iconos {
        grid-template-columns: 1fr 1fr;
    }

    .habitos-encabezado h2 {
        font-size: 34px;
    }

    .habitos-contenido {
        padding: 25px 18px;
    }
}

@media(max-width:450px) {

    .habitos-iconos {
        grid-template-columns: 1fr;
    }

    .habitos-encabezado h2 {
        font-size: 29px;
    }

    .habitos-encabezado p {
        font-size: 16px;
    }

    .video-seccion {
        padding: 23px 15px;
    }
}
</style>
