    flex-direction: column;
    gap: 20px;
    margin: 30px 0;
}

.burbuja {
    padding: 25px;
    max-width: 80%;
    box-shadow: 0 7px 18px rgba(0,0,0,.08);
    transition: .35s;
}

.burbuja:hover {
    transform: scale(1.025);
}

.burbuja h3 {
    margin: 0;
    font-family: 'Baloo 2', sans-serif;
    font-size: 24px;
}

.burbuja p {
    font-size: 17px;
    line-height: 1.7;
    margin-bottom: 0;
}

.burbuja-1 {
    background: #E8EAF6;
    border: 3px solid #5C6BC0;
    border-radius: 25px 25px 25px 5px;
}

.burbuja-1 h3 {
    color: #303f9f;
}

.burbuja-2 {
    background: #FCE4EC;
    border: 3px solid #EC407A;
    border-radius: 25px 25px 5px 25px;
    margin-left: auto;
}

.burbuja-2 h3 {
    color: #c2185b;
}

/* EMOCIONES */
.emociones-titulo {
    text-align: center;
    margin: 35px 0 25px;
}

.emociones-titulo h2 {
    font-family: 'Baloo 2', sans-serif;
    color: #283593;
    font-size: 35px;
    margin-bottom: 5px;
}

.emociones-titulo p {
    font-size: 18px;
}

.emociones {
    display: grid;
    grid-template-columns: repeat(4,1fr);
    gap: 18px;
}

.emocion {
    padding: 25px 15px;
    border-radius: 25px;
    text-align: center;
    background: white;
    box-shadow: 0 8px 20px rgba(0,0,0,.10);
    transition: .4s;
}

.emocion:hover {
    transform: translateY(-10px) rotate(1deg);
}

.emocion .emoji {
    font-size: 60px;
    animation: flotar 3s ease-in-out infinite;
}

.emocion h3 {
    font-family: 'Baloo 2', sans-serif;
    font-size: 23px;
    margin: 8px 0;
}

.emocion p {
    font-size: 16px;
    line-height: 1.6;
}

/* COLORES CONTRASTANTES */
.alegria {
    background: #FFF3CD;
    border-bottom: 7px solid #FFB300;
}

.alegria h3 {
    color: #E65100;
}

.tristeza {
    background: #D9F0FF;
    border-bottom: 7px solid #0288D1;
}

.tristeza h3 {
    color: #01579B;
}

.enojo {
    background: #FFE0E0;
    border-bottom: 7px solid #E53935;
}

.enojo h3 {
    color: #B71C1C;
}

.miedo {
    background: #EDE7F6;
    border-bottom: 7px solid #7B1FA2;
}

.miedo h3 {
    color: #6A1B9A;
}

/* VIDEO */
.video-mental {
    margin-top: 35px;
    padding: 32px;
    border-radius: 30px;
    text-align: center;
    background: linear-gradient(135deg,#E0F2F1,#B2EBF2);
    border: 3px solid #26A69A;
    box-shadow: 0 9px 22px rgba(0,0,0,.08);
}

.video-mental h2 {
    font-family: 'Baloo 2', sans-serif;
    color: #00695C;
    font-size: 32px;
    margin-top: 0;
}

.video-mental p {
    font-size: 18px;
    line-height: 1.7;
}

.video-mental iframe {
    max-width: 100%;
    border: 5px solid white;
    border-radius: 22px;
    box-shadow: 0 10px 25px rgba(0,0,0,.20);
    transition: .4s;
}

.video-mental iframe:hover {
    transform: scale(1.015);
}

/* REFLEXIÓN */
.reflexion {
    position: relative;
    overflow: hidden;
    margin-top: 30px;
    padding: 35px 25px;
    border-radius: 30px;
    color: white;
    text-align: center;
    background: linear-gradient(135deg,#FF7043,#F4511E,#AD1457);
    box-shadow: 0 10px 25px rgba(173,20,87,.22);
}

.reflexion:after {
    content: "🌈";
    position: absolute;
    right: 15px;
    top: -20px;
    font-size: 100px;
    opacity: .12;
}

.reflexion h2 {
    font-family: 'Baloo 2', sans-serif;
    font-size: 34px;
    margin-top: 0;
}

.reflexion p {
    font-size: 19px;
    line-height: 1.8;
    font-weight: 600;
}

/* ANIMACIONES */
@keyframes flotar {
    0%,100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-9px);
    }
}

@keyframes rebote {
    0%,100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-12px) rotate(3deg);
    }
}

@keyframes burbuja {
    0%,100% {
        transform: translateY(0) rotate(-5deg);
    }
    50% {
        transform: translateY(-12px) rotate(5deg);
    }
}

/* RESPONSIVE */
@media(max-width:750px) {
    .emociones {
        grid-template-columns: 1fr 1fr;
    }

    .mental-banner h1 {
        font-size: 36px;
    }
}

@media(max-width:480px) {
    .emociones {
        grid-template-columns: 1fr;
    }

    .burbuja {
        max-width: 100%;
    }

    .mental-banner h1 {
        font-size: 30px;
    }
}
</style>
<div class="salud-mental"><!-- BANNER -->
<div class="mental-banner">
<div class="icono">🧠💭✨</div>
<h1>🧠 ¿Qué pasa en tu mente?</h1>
<p>Conocer tus emociones también es una forma de cuidar tu salud.</p>
</div>
<!-- BURBUJAS -->
<div class="burbujas">
<div class="burbuja burbuja-1">
<h3>💭 ¿Qué es la salud mental y emocional?</h3>
<p>Tiene que ver con la manera en que <strong>piensas, sientes y reaccionas</strong> frente a las situaciones de la vida cotidiana.</p>
</div>
<div class="burbuja burbuja-2">
<h3>😊 Un dato importante</h3>
<p>No significa estar feliz todo el tiempo. Todos tenemos días buenos y días difíciles, y eso es completamente normal.</p>
</div>
</div>
<!-- TÍTULO EMOCIONES -->
<div class="emociones-titulo">
<h2>❤️ ¿Qué estás sintiendo hoy?</h2>
<p>Las emociones aparecen en diferentes momentos y todas cumplen una función.</p>
</div>
<!-- EMOCIONES -->
<div class="emociones">
<div class="emocion alegria">
<div class="emoji">😄</div>
<h3>Alegría</h3>
<p>Cuando ocurre algo que te hace sentir bien.</p>
</div>
<div class="emocion tristeza">
<div class="emoji">😢</div>
<h3>Tristeza</h3>
<p>Cuando algo te afecta o pierdes algo importante.</p>
</div>
<div class="emocion enojo">
<div class="emoji">😠</div>
<h3>Enojo</h3>
<p>Cuando las cosas no salen como esperabas.</p>
</div>
<div class="emocion miedo">
<div class="emoji">😨</div>
<h3>Miedo</h3>
<p>Cuando sientes preocupación o percibes un riesgo.</p>
</div>
</div>
<!-- VIDEO -->
<div class="video-mental">
<h2>🎥 Descubre más sobre tus emociones</h2>
