@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Nunito:wght@500;600;700;800;900&display=swap');

.salud-integral {
    max-width: 1100px;
    margin: 30px auto;
    padding: 0 18px;
    font-family: 'Nunito', sans-serif;
    color: #243b38;
}

/* =========================
   TITULO PRINCIPAL
========================= */

.salud-integral .hero {
    position: relative;
    overflow: hidden;
    padding: 60px 25px;
    text-align: center;
    border-radius: 38px;
    color: white;
    background: linear-gradient(135deg, #064e3b, #059669, #14b8a6);
    box-shadow: 0 20px 45px rgba(0,100,75,.25);
}

.salud-integral .hero::before {
    content: "🥦";
    position: absolute;
    font-size: 180px;
    opacity: .09;
    left: -30px;
    bottom: -60px;
}

.salud-integral .hero::after {
    content: "💤";
    position: absolute;
    font-size: 170px;
    opacity: .09;
    right: -25px;
    top: -55px;
}

.salud-integral .hero-icon {
    font-size: 75px;
    position: relative;
    z-index: 2;
}

.salud-integral .hero h1 {
    font-family: 'Baloo 2', cursive;
    font-size: 60px;
    line-height: 1;
    margin: 12px 0;
    font-weight: 800;
    position: relative;
    z-index: 2;
    text-shadow: 4px 5px 0 rgba(0,70,50,.35);
}

.salud-integral .hero p {
    font-size: 19px;
    font-weight: 700;
    position: relative;
    z-index: 2;
}

/* =========================
   SECCIONES
========================= */

.salud-integral .seccion {
    margin-top: 55px;
}

.salud-integral .titulo {
    text-align: center;
    margin-bottom: 28px;
}

.salud-integral .titulo .numero {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 46px;
    height: 46px;
    border-radius: 50%;
    background: #10b981;
    color: white;
    font-weight: 900;
    margin-bottom: 8px;
}

.salud-integral .titulo h2 {
    font-family: 'Baloo 2', cursive;
    font-size: 44px;
    line-height: 1;
    margin: 0;
    color: #064e3b;
}

.salud-integral .titulo h2 span {
    color: #10a982;
}

/* =========================
   SUSTANCIAS
========================= */

.sustancias-grid {
    display: grid;
    grid-template-columns: repeat(4,1fr);
    gap: 18px;
}

.sustancia {
    padding: 30px 18px;
    border-radius: 27px;
    color: white;
    text-align: center;
    min-height: 210px;
    transition: .35s;
    box-shadow: 0 10px 25px rgba(0,0,0,.1);
}

.sustancia:hover {
    transform: translateY(-10px) rotate(-1deg);
    box-shadow: 0 20px 35px rgba(0,0,0,.18);
}

.sustancia:nth-child(1) {
    background: linear-gradient(145deg,#374151,#111827);
}

.sustancia:nth-child(2) {
    background: linear-gradient(145deg,#f59e0b,#d97706);
}

.sustancia:nth-child(3) {
    background: linear-gradient(145deg,#06b6d4,#0284c7);
}

.sustancia:nth-child(4) {
    background: linear-gradient(145deg,#8b5cf6,#6d28d9);
}

.sustancia .icono {
    font-size: 55px;
}

.sustancia h3 {
    font-family: 'Baloo 2', cursive;
    font-size: 27px;
    margin: 12px 0 0;
}

/* =========================
   CONSECUENCIAS
========================= */

.consecuencias {
    background: #fff1f2;
    border-radius: 35px;
    padding: 38px;
    border-left: 8px solid #ef4444;
}

.consecuencias h2 {
    font-family: 'Baloo 2', cursive;
    color: #be123c;
    font-size: 40px;
    margin: 0 0 25px;
}

.consecuencias-grid {
    display: grid;
    grid-template-columns: repeat(2,1fr);
    gap: 17px;
}

.consecuencia {
    background: white;
    border-radius: 18px;
    padding: 20px;
    display: flex;
    align-items: center;
    gap: 15px;
    box-shadow: 0 6px 15px rgba(0,0,0,.06);
    transition: .3s;
}

.consecuencia:hover {
    transform: translateX(8px);
}

.consecuencia .icono {
    font-size: 35px;
}

.consecuencia strong {
    font-size: 17px;
}

/* =========================
   PROTECCION
========================= */

.proteccion {
    background: linear-gradient(135deg,#ecfdf5,#d1fae5);
    padding: 40px;
    border-radius: 35px;
}

.proteccion h2 {
    font-family: 'Baloo 2', cursive;
    text-align: center;
    font-size: 42px;
    color: #047857;
    margin: 0 0 30px;
}

.proteccion-grid {
    display: grid;
    grid-template-columns: repeat(4,1fr);
    gap: 18px;
}

.proteccion-card {
    background: white;
    border-radius: 23px;
    padding: 25px 18px;
    text-align: center;
    border-bottom: 5px solid #10b981;
    transition: .3s;
}

.proteccion-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 12px 25px rgba(0,0,0,.1);
}

.proteccion-card .icono {
    font-size: 45px;
}

.proteccion-card h3 {
    color: #047857;
    font-size: 18px;
}

/* =========================
   ALIMENTACION
========================= */

.alimentacion {
    background: linear-gradient(135deg,#fff7ed,#ffedd5);
    border-radius: 38px;
    padding: 45px;
}

.alimentacion-titulo {
    text-align: center;
}

.alimentacion-titulo .icono {
    font-size: 70px;
}

.alimentacion h2 {
    font-family: 'Baloo 2', cursive;
    font-size: 48px;
    line-height: 1;
    color: #c2410c;
    margin: 10px 0;
}

.alimentacion-intro {
    max-width: 750px;
    margin: 15px auto 30px;
    text-align: center;
    font-size: 18px;
    line-height: 1.7;
}

.alimentos-grid {
    display: grid;
    grid-template-columns: repeat(4,1fr);
    gap: 18px;
}

.alimento {
    background: white;
    border-radius: 24px;
    padding: 25px 15px;
    text-align: center;
    transition: .3s;
    box-shadow: 0 7px 18px rgba(0,0,0,.06);
}

.alimento:hover {
    transform: scale(1.04);
}

.alimento .emoji {
    font-size: 48px;
}

.alimento h3 {
    font-family: 'Baloo 2', cursive;
    font-size: 23px;
    color: #c2410c;
    margin: 10px 0 0;
}

/* =========================
   SUEÑO
========================= */

.sueno {
    background: #111827;
    color: white;
    border-radius: 38px;
    padding: 45px;
    position: relative;
    overflow: hidden;
}

.sueno::before {
    content: "⭐";
    position: absolute;
    font-size: 160px;
    opacity: .06;
    right: -20px;
    top: -30px;
}

.sueno-titulo {
    text-align: center;
}

.sueno-titulo .icono {
    font-size: 70px;
}

.sueno h2 {
    font-family: 'Baloo 2', cursive;
    font-size: 48px;
    margin: 5px 0;
    color: #a5f3fc;
}

.sueno h3 {
    text-align: center;
    font-size: 21px;
    color: #d1d5db;
    margin-bottom: 30px;
}

.sueno-grid {
    display: grid;
    grid-template-columns: repeat(3,1fr);
    gap: 18px;
}

.sueno-card {
    background: #1f2937;
    border: 2px solid #374151;
    border-radius: 23px;
    padding: 28px 18px;
    text-align: center;
    transition: .3s;
}

.sueno-card:hover {
    transform: translateY(-8px);
    background: #273449;
    border-color: #67e8f9;
}

.sueno-card .emoji {
    font-size: 48px;
}

.sueno-card h4 {
    font-size: 19px;
    color: #67e8f9;
}

/* CONSEJO */
.consejo {
    margin-top: 25px;
    background: linear-gradient(135deg,#0891b2,#2563eb);
    border-radius: 25px;
    padding: 25px;
    text-align: center;
    position: relative;
    z-index: 2;
}

.consejo strong {
    font-family: 'Baloo 2', cursive;
    font-size: 27px;
}

/* =========================
   RESPONSIVE
========================= */

@media(max-width:800px) {

    .sustancias-grid,
    .proteccion-grid,
    .alimentos-grid {
        grid-template-columns: 1fr 1fr;
    }

    .sueno-grid {
        grid-template-columns: 1fr;
    }

    .salud-integral .hero h1 {
        font-size: 48px;
    }
}

@media(max-width:500px) {

    .sustancias-grid,
    .proteccion-grid,
