    .consecuencias h2,
    .proteccion h2 {
        font-size: 34px;
    }

    .alimentacion h2,
    .sueno h2 {
        font-size: 38px;
    }

    .alimentacion,
    .proteccion,
    .consecuencias,
    .sueno {
        padding: 28px 20px;
    }
}
